-- Per-community "nearest real place" enrichment
-- (dubai_communities_nearest_locations.csv, 3618 rows): for
-- each of the 201 communities in
-- patch_123, the top 3 nearest real named places per category (Schools,
-- Hospitals, Transport, Lifestyle, Restaurants, Attractions), each with
-- both straight-line distance_km and a real estimated driving distance
-- (est_drive_km) -- more useful for a real-estate buyer than straight-line
-- alone. Matched to communities.id by name (all 3618 rows'
-- community names come from the same source list as patch_123, already
-- confirmed to match 1:1), so this patch must run after patch_123.

create table if not exists community_nearest_locations (
  id uuid primary key default gen_random_uuid(),
  community_id uuid not null references communities(id) on delete cascade,
  category text not null,
  rank int not null,
  poi_name text not null,
  poi_lat numeric not null,
  poi_lng numeric not null,
  distance_km numeric not null,
  est_drive_km numeric not null,
  created_at timestamptz not null default now()
);
create index if not exists community_nearest_locations_community_id_idx on community_nearest_locations(community_id);

alter table community_nearest_locations enable row level security;
drop policy if exists "community_nearest_locations: public read" on community_nearest_locations;
create policy "community_nearest_locations: public read" on community_nearest_locations for select using (true);

insert into community_nearest_locations (community_id, category, rank, poi_name, poi_lat, poi_lng, distance_km, est_drive_km)
